import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        # Store net balances as integer cents to avoid floating-point inaccuracies
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be greater than zero.")
        if payer not in self._balances:
            raise ValueError(f"Payer '{payer}' is not a member of the group.")

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)

        if not parts:
            raise ValueError("Participants list cannot be empty.")

        for p in parts:
            if p not in self._balances:
                raise ValueError(f"Participant '{p}' is not a member of the group.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Requirement 2: Every other participant owes amount rounded down to the cent.
        # The leftover cents are borne by the payer.
        base_cents = total_cents // n
        remainder_cents = total_cents % n

        # Total amount owed by participants (excluding payer's own base share)
        if payer in parts:
            # Payer owes base_cents + remainder_cents, so others owe base_cents each
            for p in parts:
                if p != payer:
                    self._balances[p] -= base_cents
                    self._balances[payer] += base_cents
        else:
            # Payer is not in participants: each participant owes base_cents,
            # remainder is absorbed/forgiven by the payer (borne by the payer).
            for p in parts:
                self._balances[p] -= base_cents
                self._balances[payer] += base_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors (net negative) and Creditors (net positive) in cents
        debtors = []
        creditors = []

        for m in self.members:
            bal = self._balances[m]
            if bal < 0:
                debtors.append([m, -bal])
            elif bal > 0:
                creditors.append([m, bal])

        payments: list[tuple[str, str, float]] = []

        i = 0
        j = 0
        while i < len(debtors) and j < len(creditors):
            debtor_name, debt_cents = debtors[i]
            creditor_name, credit_cents = creditors[j]

            pay_cents = min(debt_cents, credit_cents)

            # Requirement 4: Debts below 1.00 (100 cents) are written off
            if pay_cents >= 100:
                payments.append(
                    (debtor_name, creditor_name, round(pay_cents / 100.0, 2))
                )

            debtors[i][1] -= pay_cents
            creditors[j][1] -= pay_cents

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return payments
